intfalsesocket_sendmsg Socketsocket arraymessage intflags0
A função socket_sendmsg envia a mensagem descrita por message por meio do socket socket, usando a chamada de sistema sendmsg().

  &reftitle.examples;

   Enviando uma mensagem com socket_sendmsg


<?php
$server = socket_create(AF_INET, SOCK_DGRAM, SOL_UDP);
socket_bind($server, '127.0.0.1', 1053);

$client = socket_create(AF_INET, SOCK_DGRAM, SOL_UDP);
$sent = socket_sendmsg($client, [
    'name' => ['addr' => '127.0.0.1', 'port' => 1053],
    'iov'  => ['Hello ', 'world'],
], 0);

echo "enviado: $sent\n";

socket_recvfrom($server, $buffer, 64, 0, $from, $port);
echo "recebido: $buffer\n";
?>


   &example.outputs;


enviado: 11
recebido: Hello world




   Passando um descritor de arquivo por um socket UNIX

    A chave control transporta dados auxiliares. Com
    SCM_RIGHTS, ela transfere descritores de arquivo abertos para o processo na outra
    extremidade de um socket UNIX. Isso não está disponível no Windows.



<?php
socket_create_pair(AF_UNIX, SOCK_STREAM, 0, $pair);
[$sender, $receiver] = $pair;

$file = fopen(__FILE__, 'r');

socket_sendmsg($sender, [
    // Pelo menos um byte de dados comuns deve acompanhar os dados auxiliares.
    'iov'     => ['fd'],
    'control' => [
        ['level' => SOL_SOCKET, 'type' => SCM_RIGHTS, 'data' => [$file]],
    ],
], 0);

$message = [
    'buffer_size' => 16,
    'controllen'  => socket_cmsg_space(SOL_SOCKET, SCM_RIGHTS, 1),
];
socket_recvmsg($receiver, $message, 0);

$received = $message['control'][0]['data'][0];
echo "primeira linha: ", fgets($received);
?>


   &example.outputs;


primeira linha: <?php
